    select * FROM (
        select ROWNUM as rnum, A.* from (
            select * from dc_community


                    AND comm_type = #{comm_type}


                    AND comm_pet_type = #{comm_pet_type}


                    AND comm_category = #{comm_category}




                    ORDER BY comm_count DESC, comm_no DESC


                    ORDER BY comm_date DESC


	        ) A
	        WHERE ROWNUM <= #{endRow}
	    )
	    WHERE rnum >= #{startRow}

select count(*) from dc_community


        AND comm_type = #{comm_type}


        AND comm_pet_type = #{comm_pet_type}


        AND comm_category = #{comm_category}

mapper.update:
update dc_community
set comm_view = comm_view + 1
where comm_no = #{comm_no}
